mod support;

use speedyspec_hooks::{Key, Value};
use speedyspec_wp_theme_json::selectors::*;
use speedyspec_wp_theme_json_contracts::ports::RegisteredBlock;
use support::{assert_php_same as assert_php_eq, json, opt, st};

fn speedyspec_hooks_list(items: Vec<String>) -> Value {
    Value::Array(
        items
            .into_iter()
            .enumerate()
            .map(|(i, s)| (Key::Int(i as i64), Value::Str(s)))
            .collect(),
    )
}

